246: function applyZombieAsset(zombie) {
247:   if (zombie.isBoss || !zombieAsset.root || !window.THREE.SkeletonUtils) return false;
248:   const replacement = THREE.SkeletonUtils.clone(zombieAsset.root);
249:   replacement.traverse((part) => {
250:     if (!part.isMesh) return;
251:     part.castShadow = true;
252:     part.receiveShadow = true;
253:     const cloneMaterial = (material) => {
254:       const instance = material.clone();
255:       if (instance.color) instance.color.multiplyScalar(1.12);
256:       if (instance.color && zombie.variant.tint !== 0xffffff) instance.color.multiply(new THREE.Color(zombie.variant.tint));
257:       if (instance.emissive && instance.emissive.getHex() !== 0) instance.emissive.multiplyScalar(1.1);
258:       if (instance.emissive) instance.userData.baseEmissive = instance.emissive.clone();
259:       return instance;
260:     };
261:     part.material = Array.isArray(part.material) ? part.material.map(cloneMaterial) : cloneMaterial(part.material);
262:   });
263:   replacement.updateWorldMatrix(true, true);
264:   const bounds = new THREE.Box3().setFromObject(replacement);
265:   const size = bounds.getSize(new THREE.Vector3());
266:   if (!Number.isFinite(size.y) || size.y < 0.1) return false;
267:   const center = bounds.getCenter(new THREE.Vector3());
268:   const scale = (1.65 * zombie.variant.modelScale) / size.y;
269:   replacement.scale.setScalar(scale);
270:   replacement.position.set(-center.x * scale, -bounds.min.y * scale, -center.z * scale);
271:   const root = new THREE.Group();
272:   root.add(replacement);
273:   addZombieHealthBar(zombie, root);
274:   if (zombie.model) {
275:     scene.remove(zombie.model);
276:     zombie.model.traverse((part) => { if (part.geometry) part.geometry.dispose(); });
277:   }
278:   scene.add(root);
279:   zombie.model = root;
280:   zombie.limbs = [];
281:   zombie.mixer = new THREE.AnimationMixer(replacement);
282:   if (zombieAsset.clips.length) {
283:     zombie.action = zombie.mixer.clipAction(zombieAsset.clips[0]);
284:     zombie.action.setLoop(THREE.LoopRepeat, Infinity);
