691: function updatePlayer(dt) {
692:   const player = world.player;
693:   let dx = 0; let dy = 0;
694:   if (input.keys.has('w') || input.keys.has('arrowup')) dy -= 1;
695:   if (input.keys.has('s') || input.keys.has('arrowdown')) dy += 1;
696:   if (input.keys.has('a') || input.keys.has('arrowleft')) dx -= 1;
697:   if (input.keys.has('d') || input.keys.has('arrowright')) dx += 1;
698:   if (input.touchStick.active) { dx += input.touchStick.x; dy += input.touchStick.y; }
699:   const length = Math.hypot(dx, dy) || 1;
700:   player.x = clamp(player.x + dx / length * player.speed * dt, 20, world.width - 20);
701:   player.y = clamp(player.y + dy / length * player.speed * dt, 20, world.height - 20);
702:   if (player.regen > 0 && player.hp < player.maxHp) player.hp = Math.min(player.maxHp, player.hp + player.regen * dt);
703:   player.orbitTimer = Math.max(0, player.orbitTimer - dt);
704:   let target = null; let targetDistance = 650;
705:   for (const zombie of world.zombies) {
706:     const distance = dist(player.x, player.y, zombie.x, zombie.y);
707:     if (distance < targetDistance) { target = zombie; targetDistance = distance; }
708:   }
709:   if (target) {
710:     player.angle = Math.atan2(target.y - player.y, target.x - player.x);
711:     player.fireCooldown -= dt;
712:     if (player.fireCooldown <= 0) { fireBullet(); player.fireCooldown = player.fireRate; }
713:   } else player.fireCooldown = Math.min(player.fireCooldown, 0);
714:   player.model.rotation.y = Math.PI / 2 - player.angle;
715:   syncEntity(player);
716:   player.bombCooldown = Math.max(0, player.bombCooldown - dt);
717:   if (input.bomb) { input.bomb = false; if (player.bombCooldown <= 0) throwBomb(); }
718:   if (player.invuln > 0) player.invuln -= dt;
719:   if (player.gunFlash > 0) player.gunFlash -= dt;
720:   updateWeaponLabel();
721: }
