  await page.locator('#startButton').click();
  await page.waitForFunction(() => document.getElementById('overlay').classList.contains('hidden'), { timeout: 15000 });
  const chain = await page.evaluate(() => {
    const t = window.__gameTest, w = t.world, p = w.player;
    p.chainLevel = 3; p.damage = 100; p.angle = 0;
    for (const z of [...w.zombies]) { if (z.model) z.model.parent?.remove(z.model); }
    w.zombies = []; w.bullets = []; w.kills = 0;
    const positions = [85, 145, 220, 295];
    const targets = positions.map(dx => {
      const z = t.createZombie(p.x + dx, p.y);
      z.hp = 1; z.maxHp = 1; z.armor = 0; w.zombies.push(z); return z;
    });
    t.fireBullet();
    t.updateBullets(0.1);
    const afterHit = { remaining: w.zombies.length, kills: w.kills, lightningSegments: w.lightning.length, pickupCount: w.pickups.length };
    t.updateLightning(0.2);
    const effectsCleared = w.lightning.length === 0;
    t.resetGame();
    const resetState = { running: w.running, chainLevel: w.player.chainLevel, lightning: w.lightning.length, wave: w.wave, zombies: w.zombies.length };
    return { afterHit, effectsCleared, resetState, targetCount: targets.length };
  });
  await page.evaluate(() => window.__gameTest.finishGame());
  await page.waitForSelector('#restartButton', { state: 'visible' });
  await page.locator('#restartButton').click();
  await page.waitForFunction(() => document.getElementById('overlay').classList.contains('hidden'), { timeout: 15000 });
  const restart = await page.evaluate(() => ({ running: window.__gameTest.world.running, gameOver: window.__gameTest.world.gameOver, level: window.__gameTest.world.player.level, chainLevel: window.__gameTest.world.player.chainLevel }));
